from __future__ import annotations

import json
import re
from contextlib import contextmanager
from datetime import UTC, datetime, timedelta
from hashlib import sha256
from typing import Any

from packages.common.pg_native import PostgresMigration, apply_schema_migrations, connect_postgres, postgres_transaction
from packages.common.storage import load_storage_settings
from .repository import _cursor_key, _date_boundary, _iso, _without_urls

SCHEMA_SQL = """
CREATE TABLE IF NOT EXISTS business_telegram_groups(chat_id text PRIMARY KEY,chat_title text NOT NULL DEFAULT '',chat_username text,customer_name text NOT NULL DEFAULT '',is_enabled boolean NOT NULL DEFAULT false,discovered_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,last_message_at timestamptz);
CREATE INDEX IF NOT EXISTS idx_business_telegram_groups_enabled ON business_telegram_groups(is_enabled,discovered_at DESC);
CREATE TABLE IF NOT EXISTS business_message_inbox(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,update_id bigint NOT NULL UNIQUE,chat_id text NOT NULL REFERENCES business_telegram_groups(chat_id),message_id bigint NOT NULL,sender_id text NOT NULL DEFAULT '',sender_name text NOT NULL DEFAULT '',received_at timestamptz NOT NULL,message_date timestamptz,is_text boolean NOT NULL DEFAULT false,raw_text text,classification text,classification_reason text,writing_style text,writer4_title text,writer4_content text,writer2_title text,writer2_content text,source_url text,status text NOT NULL,status_reason text,push_result jsonb,plugin_notice_result jsonb,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(chat_id,message_id),odaily_external_error_counted integer NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_business_message_inbox_status ON business_message_inbox(status,received_at,id);
CREATE INDEX IF NOT EXISTS idx_business_message_inbox_chat_time ON business_message_inbox(chat_id,received_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS idx_business_message_inbox_classification ON business_message_inbox(classification,status,received_at DESC);
CREATE TABLE IF NOT EXISTS business_telegram_recent_messages(chat_id text NOT NULL,message_id bigint NOT NULL,sender_id text NOT NULL DEFAULT '',received_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,text_content text,urls_json jsonb NOT NULL DEFAULT '[]',PRIMARY KEY(chat_id,message_id));
CREATE INDEX IF NOT EXISTS idx_business_recent_messages_expiry ON business_telegram_recent_messages(expires_at);
CREATE TABLE IF NOT EXISTS business_telegram_state(state_key text PRIMARY KEY,state_value text NOT NULL,updated_at timestamptz NOT NULL);
"""


def _as_json(value):
    if value is None:return None
    if not isinstance(value,str):return value
    try:return json.loads(value)
    except json.JSONDecodeError:return value


class PostgresBusinessNewsRepository:
    def __init__(self): self.backend='postgres'; self.initialize()
    @contextmanager
    def _connect(self):
        with connect_postgres(schema='business_news',application_name='odaily-business-news') as c:
            with postgres_transaction(c): yield c
    def initialize(self):
        self.initialize_schema()

    @staticmethod
    def initialize_schema():
        with connect_postgres(schema='business_news',application_name='odaily-business-news-migrate') as c:
            apply_schema_migrations(c,schema='business_news',component='business_news',migrations=(PostgresMigration(1,'business_news_initial',sha256(SCHEMA_SQL.encode()).hexdigest(),lambda x:x.execute(SCHEMA_SQL)),))
    def last_update_id(self,bot_id=None):
        with self._connect() as c:r=c.execute('SELECT state_value FROM business_telegram_state WHERE state_key=%s',(_cursor_key(bot_id),)).fetchone()
        return int(r['state_value']) if r else None
    def _save_cursor_in(self,c,update_id,bot_id=None):
        c.execute("INSERT INTO business_telegram_state VALUES(%s,%s,now()) ON CONFLICT(state_key) DO UPDATE SET state_value=GREATEST(business_telegram_state.state_value::bigint,excluded.state_value::bigint)::text,updated_at=excluded.updated_at",(_cursor_key(bot_id),str(update_id)))
    def _save_cursor(self,update_id,bot_id=None):
        with self._connect() as c:self._save_cursor_in(c,update_id,bot_id)
    def ingest_update(self,update,*,source_urls,link_only=False,own_bot_id,startup_backfill=False,bot_id=None):
        update_id=update.get('update_id')
        if not isinstance(update_id,int):return None
        message=update.get('message'); member=update.get('my_chat_member'); payload=message if isinstance(message,dict) else member if isinstance(member,dict) else None; chat=payload.get('chat') if isinstance(payload,dict) else None
        if not isinstance(chat,dict) or chat.get('type') not in {'group','supergroup'}:
            self._save_cursor(update_id,bot_id); return None
        chat_id=str(chat.get('id') or '').strip()
        if not chat_id:self._save_cursor(update_id,bot_id);return None
        title=str(chat.get('title') or chat.get('username') or '').strip(); username=str(chat.get('username') or '').strip() or None; now=datetime.now(UTC)
        message_id=message.get('message_id') if isinstance(message,dict) else None; sender=message.get('from') if isinstance(message,dict) else {}; sender=sender if isinstance(sender,dict) else {}; sender_chat=message.get('sender_chat') if isinstance(message,dict) else None
        sender_id=str(sender.get('id') or (sender_chat or {}).get('id') or ''); sender_name=' '.join(str(sender.get(k) or '').strip() for k in ('first_name','last_name') if str(sender.get(k) or '').strip()) or str(sender.get('username') or (sender_chat or {}).get('title') or '').strip()
        text=message.get('text') if isinstance(message,dict) else None
        if not isinstance(text,str) and isinstance(message,dict):text=message.get('caption')
        if not isinstance(text,str) or not text.strip():text=None
        with self._connect() as c:
            existed=c.execute('SELECT 1 FROM business_telegram_groups WHERE chat_id=%s',(chat_id,)).fetchone() is not None
            c.execute("INSERT INTO business_telegram_groups(chat_id,chat_title,chat_username,discovered_at,updated_at) VALUES(%s,%s,%s,%s,%s) ON CONFLICT(chat_id) DO UPDATE SET chat_title=CASE WHEN excluded.chat_title<>'' THEN excluded.chat_title ELSE business_telegram_groups.chat_title END,chat_username=coalesce(excluded.chat_username,business_telegram_groups.chat_username),updated_at=excluded.updated_at",(chat_id,title,username,now,now))
            group=c.execute('SELECT is_enabled FROM business_telegram_groups WHERE chat_id=%s',(chat_id,)).fetchone()
            if isinstance(message,dict):c.execute('UPDATE business_telegram_groups SET last_message_at=%s,updated_at=%s WHERE chat_id=%s',(now,now,chat_id))
            if isinstance(message,dict) and isinstance(message_id,int) and text is not None and group['is_enabled'] and not startup_backfill and str(sender.get('id') or '')!=str(own_bot_id or ''):
                compact=sum(1 for ch in _without_urls(text) if not ch.isspace()); status,reason,stored=('skipped_link','纯链接内容，不生成快讯',None) if link_only else ('filtered_short','去掉空白和 URL 后不足 15 字',None) if compact<15 else ('pending',None,text)
                try: msg_date=datetime.fromtimestamp(int(message.get('date')),UTC)
                except (TypeError,ValueError,OverflowError):msg_date=None
                c.execute(
                    """INSERT INTO business_message_inbox(
                           update_id,chat_id,message_id,sender_id,sender_name,received_at,message_date,
                           is_text,raw_text,source_url,status,status_reason,created_at,updated_at
                       ) VALUES(%s,%s,%s,%s,%s,%s,%s,true,%s,%s,%s,%s,%s,%s)
                       ON CONFLICT DO NOTHING""",
                    (update_id,chat_id,message_id,sender_id,sender_name,now,msg_date,stored,
                     source_urls[0] if source_urls else None,status,reason,now,now),
                )
                c.execute("INSERT INTO business_telegram_recent_messages(chat_id,message_id,sender_id,received_at,expires_at,text_content,urls_json) VALUES(%s,%s,%s,%s,%s,%s,%s) ON CONFLICT(chat_id,message_id) DO UPDATE SET sender_id=excluded.sender_id,received_at=excluded.received_at,expires_at=excluded.expires_at,text_content=excluded.text_content,urls_json=excluded.urls_json",(chat_id,message_id,sender_id,now,now+timedelta(minutes=10),text,json.dumps(source_urls,ensure_ascii=False)))
            c.execute('DELETE FROM business_telegram_recent_messages WHERE expires_at<%s',(now,)); self._save_cursor_in(c,update_id,bot_id)
        return {'chat_id':chat_id,'chat_title':title,'update_id':update_id,'message_id':message_id,'newly_discovered':not existed}
    def claim_pending(self,limit=4):
        with self._connect() as c:
            rows=c.execute("SELECT m.*,g.customer_name FROM business_message_inbox m JOIN business_telegram_groups g USING(chat_id) WHERE m.status='pending' ORDER BY m.id LIMIT %s FOR UPDATE OF m SKIP LOCKED",(max(1,min(32,int(limit))),)).fetchall()
            ids=[r['id'] for r in rows]
            if ids:c.execute("UPDATE business_message_inbox SET status='processing',updated_at=now() WHERE id=ANY(%s) AND status='pending'",(ids,))
        return [dict(r) for r in rows]
    def discard_interrupted(self):
        with self._connect() as c:r=c.execute("UPDATE business_message_inbox SET status='discarded_failure',status_reason='服务中断，按不重试规则丢弃',raw_text=NULL,updated_at=now() WHERE status IN ('processing','formatting','publishing')")
        return r.rowcount
    def adjacent_urls(self,item):
        with self._connect() as c:
            p=c.execute('SELECT sender_id,urls_json FROM business_telegram_recent_messages WHERE chat_id=%s AND message_id<%s AND expires_at>=now() ORDER BY message_id DESC LIMIT 1',(item['chat_id'],item['message_id'])).fetchone(); n=c.execute('SELECT sender_id,urls_json FROM business_telegram_recent_messages WHERE chat_id=%s AND message_id>%s AND expires_at>=now() ORDER BY message_id LIMIT 1',(item['chat_id'],item['message_id'])).fetchone()
        previous = _as_json(p['urls_json']) if p and p['sender_id']==item['sender_id'] else []
        following = _as_json(n['urls_json']) if n and n['sender_id']==item['sender_id'] else []
        return (previous if isinstance(previous, list) else [], following if isinstance(following, list) else [])
    def update_message(self,inbox_id,**fields):
        allowed={'classification','classification_reason','writing_style','writer4_title','writer4_content','writer2_title','writer2_content','source_url','status','status_reason','push_result','plugin_notice_result','raw_text'}; updates={k:v for k,v in fields.items() if k in allowed}
        if not updates:return
        updates['updated_at']=datetime.now(UTC)
        for key in ('push_result','plugin_notice_result'):
            if key in updates and isinstance(updates[key],(dict,list)):updates[key]=json.dumps(updates[key],ensure_ascii=False)
        cols=list(updates)
        with self._connect() as c:c.execute(f"UPDATE business_message_inbox SET {','.join(k+'=%s' for k in cols)} WHERE id=%s",(*[updates[k] for k in cols],inbox_id))
    def list_dashboard(self,payload):
        page=max(0,int(payload.get('page') or 0)); size=max(1,min(100,int(payload.get('page_size') or 50))); filters=["m.status<>'skipped_non_text'"]; values=[]
        for key,col in (('chat_id','m.chat_id'),('classification','m.classification'),('status','m.status')):
            val=str(payload.get(key) or '').strip()
            if val:filters.append(f'{col}=%s');values.append(val)
        for key,end in (('date_from',False),('date_to',True)):
            val=str(payload.get(key) or '').strip()
            if val:filters.append(('m.received_at<' if end else 'm.received_at>=')+'%s');values.append(_date_boundary(val,end=end))
        query=str(payload.get('query') or '').strip()[:120]
        if query:filters.append('(m.raw_text ILIKE %s OR m.writer4_title ILIKE %s OR m.writer4_content ILIKE %s OR m.classification_reason ILIKE %s OR g.chat_title ILIKE %s)');values.extend([f'%{query}%']*5)
        where=' WHERE '+' AND '.join(filters)
        with self._connect() as c:
            total=int(c.execute(f'SELECT count(*) AS n FROM business_message_inbox m JOIN business_telegram_groups g USING(chat_id){where}',values).fetchone()['n'])
            items=[dict(r) for r in c.execute(f'SELECT m.*,g.chat_title,g.customer_name FROM business_message_inbox m JOIN business_telegram_groups g USING(chat_id){where} ORDER BY m.received_at DESC,m.id DESC LIMIT %s OFFSET %s',(*values,size,page*size)).fetchall()]
            groups=[dict(r) for r in c.execute('SELECT chat_id,chat_title,chat_username,customer_name,is_enabled,discovered_at,updated_at,last_message_at FROM business_telegram_groups ORDER BY discovered_at DESC,chat_title').fetchall()]
        for item in items:
            for k in ('push_result','plugin_notice_result'):
                if isinstance(item.get(k),str):item[k]=_as_json(item[k])
        return {'items':items,'groups':groups,'total':total,'page':page,'page_size':size}
    def save_group(self,*,chat_id,customer_name,enabled):
        chat_id=str(chat_id or '').strip(); name=str(customer_name or '').strip()[:80]
        if not chat_id or not name:raise ValueError('chat_id 和客户名不能为空')
        with self._connect() as c:
            c.execute('UPDATE business_telegram_groups SET customer_name=%s,is_enabled=%s,updated_at=now() WHERE chat_id=%s',(name,enabled,chat_id)); row=c.execute('SELECT chat_id,chat_title,chat_username,customer_name,is_enabled,discovered_at,updated_at,last_message_at FROM business_telegram_groups WHERE chat_id=%s',(chat_id,)).fetchone()
        if row is None:raise ValueError('群尚未由 Telegram 自动发现')
        return dict(row)


def create_business_news_repository(database_path=None):
    if database_path is not None:raise ValueError('PostgreSQL business repository does not accept SQLite path')
    return PostgresBusinessNewsRepository() if load_storage_settings().backend=='postgres' else __import__('packages.business_news.repository',fromlist=['BusinessNewsRepository']).BusinessNewsRepository(__import__('packages.business_news.storage',fromlist=['business_news_path']).business_news_path())
